{
  "decline_reason": "",
  "claims": [
    {
      "text": "An applicant for registration or the registered owner may disclaim an exclusive right to use, or authorise the use of, a specified part of the trade mark by giving written notice to the Registrar.",
      "quotes": [
        {
          "ref": "TMA1995/s74(1)",
          "quote": "(1) An applicant for the registration of a trade mark, or the registered owner of a registered trade mark, may, by notice in writing given to the Registrar, disclaim any exclusive right to use, or authorise the use of, a specified part of the trade mark."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual states that disclaimers are voluntary and will not be requested by the Registrar.",
      "quotes": [
        {
          "ref": "TMM/Part24/1#1",
          "quote": "Under the current provisions any part or parts of a trade mark can be the subject of a disclaimer (whether descriptive or not) however, disclaimers will not be requested by the Registrar. They are voluntary only."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Under the Manual's practice, a request may be made at any time, without a fee.",
      "quotes": [
        {
          "ref": "TMM/Part24/2#1~1",
          "quote": "The request to enter a disclaimer in the Register may be made at any time by an applicant for registration of a trade mark or a registered owner of a trade mark. No fee is payable for such a request."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Registrar must enter the particulars of the disclaimer in the Register when the trade mark is registered or when notice of the disclaimer is received, whichever is later.",
      "quotes": [
        {
          "ref": "TMA1995/s74",
          "quote": "(3) The Registrar must, on registering the trade mark or on receiving notice of the disclaimer (whichever is later), enter the particulars of the disclaimer in the Register."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The disclaimer affects only the rights that the Act gives the registered owner on registration.",
      "quotes": [
        {
          "ref": "TMA1995/s74",
          "quote": "(2) The disclaimer affects only the rights given by this Act to the registered owner of the trade mark on registration of the trade mark."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual explains that the owner cannot claim statutory rights in the disclaimed parts, and that the disclaimer affects only the registrations on which it is entered.",
      "quotes": [
        {
          "ref": "TMM/Part24/3#1",
          "quote": "3.2 Registered owners cannot claim statutory rights in parts of the trade mark that have been disclaimed1. 3.3 Disclaimers only affect the registrations on which they are entered."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual states that using the disclaimed part does not infringe the registered trade mark, citing subsection 122(2); the supplied legislative passages do not include that subsection.",
      "quotes": [
        {
          "ref": "TMM/Part24/3#1",
          "quote": "3.4 A person does not infringe a registered trade mark by using that part of the trade mark which has been disclaimed (subsection 122(2))."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual explains that a disclaimer does not affect common law rights or prevent the owner succeeding in a passing off action.",
      "quotes": [
        {
          "ref": "TMM/Part24/3#1",
          "quote": "Disclaimers do not affect rights arising at common law and the fact that matter has been disclaimed in a registered trade mark does not prevent the owner succeeding in a passing off action"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "A properly made disclaimer cannot be revoked.",
      "quotes": [
        {
          "ref": "TMA1995/s74",
          "quote": "(4) A disclaimer properly made may not be revoked."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual permits amendment after registration only if it does not revoke the disclaimer or extend the scope of registration.",
      "quotes": [
        {
          "ref": "TMM/Part24/5#1",
          "quote": "5.1 After registration a disclaimer may be amended as long as the amendment does not constitute a revocation of the disclaimer or extend in any way the scope of the registration (para 83(1)(c))."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For examination, the Manual generally takes no account of a disclaimer and does not treat it as changing the trade mark's inherent capacity to distinguish.",
      "quotes": [
        {
          "ref": "TMM/Part24/4#1",
          "quote": "4.1 No account is generally taken of a disclaimer during the examination process."
        },
        {
          "ref": "TMM/Part24/4#1",
          "quote": "A disclaimer does not affect the inherent capacity, or otherwise, of a trade mark to distinguish"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For section 44 examination, the Manual requires consideration of the marks as a whole despite a disclaimed element, but recognises that a disclaimer on an earlier registered mark may sometimes be relevant as an ‘other circumstance’ under paragraph 44(3)(b).",
      "quotes": [
        {
          "ref": "TMM/Part24/4#1",
          "quote": "4.5 When considering a ground for rejection under s 44, it is necessary to consider the trade marks as a whole even if the earlier trade mark has a disclaimed element. However, there may be some cases where it may be relevant to consider a disclaimer on an earlier registered trade mark as a relevant ‘other circumstance’ under s 44(3)(b)."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0099",
    "GC-0116",
    "GC-0084",
    "GC-0046",
    "GC-0089",
    "GC-0088",
    "GC-0092",
    "GC-0059",
    "GC-0038",
    "GC-0064",
    "GC-0068"
  ]
}
